using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.IO.Pipes;
using System.Net.Security;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using PeerChatDesktop;

namespace PeerChat.ServerTests {
class DiscoveryIntegrationTest {
    sealed class RelayConnection : IDisposable { public TcpClient Tcp;public SslStream Tls;public string Session;public void Dispose(){Tls.Dispose();Tcp.Close();} }
    static void Require(bool value,string message){if(!value)throw new Exception(message);}
    static bool Fails(Action action){try{action();return false;}catch{return true;}}
    static string CoturnPassword(string username,string secret){using(var hmac=new HMACSHA1(Encoding.UTF8.GetBytes(secret)))return Convert.ToBase64String(hmac.ComputeHash(Encoding.UTF8.GetBytes(username)));}
    static Dictionary<string,object> Admin(string pipe,string command){using(var client=new NamedPipeClientStream(".",pipe,PipeDirection.InOut)){client.Connect(2000);var encoding=new UTF8Encoding(false);var writer=new StreamWriter(client,encoding,256,true);var reader=new StreamReader(client,encoding,false,256,true);writer.WriteLine(command);writer.Flush();return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(reader.ReadLine());}}
    static Dictionary<string,object> AdminAccounts(string pipe,string query,int offset=0,int limit=25){return Admin(pipe,"ACCOUNT_LIST "+offset+" "+limit+" "+Convert.ToBase64String(Encoding.UTF8.GetBytes(query??"")));}
    static RelayConnection Attach(DiscoveryClient client,string local,long targetAccount,string target){TcpClient tcp;var tls=client.OpenAuthenticatedStream(out tcp,true);var json=new JavaScriptSerializer();var request=new Dictionary<string,object>{{"version",1},{"type","relay_attach"},{"sessionToken",client.SessionToken},{"publicIdentity",local},{"targetAccountId",targetAccount.ToString()},{"targetPublicIdentity",target}};DiscoveryClient.WriteFrame(tls,Encoding.UTF8.GetBytes(json.Serialize(request)));var response=json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(DiscoveryClient.ReadFrame(tls)));object ok,error;if(!response.TryGetValue("ok",out ok)||!(bool)ok){response.TryGetValue("error",out error);tls.Dispose();tcp.Close();throw new InvalidOperationException(error as string??"relay_failed");}return new RelayConnection{Tcp=tcp,Tls=tls,Session=(string)response["sessionId"]};}
    static void RelayRoundTrip(DiscoveryClient left,string leftPeer,long leftTarget,string rightPeer,DiscoveryClient right,long rightTarget,string description,bool proveIdle=false){var a=Task.Run(()=>Attach(left,leftPeer,leftTarget,rightPeer));var b=Task.Run(()=>Attach(right,rightPeer,rightTarget,leftPeer));Task.WaitAll(a,b);using(var first=a.Result)using(var second=b.Result){Require(first.Tcp.ReceiveTimeout==0&&second.Tcp.ReceiveTimeout==0,description+" inherited the short discovery request timeout");Require(first.Session==second.Session&&first.Session.Length==43,description+" did not receive one bound session");byte[] prefix=Encoding.ASCII.GetBytes(first.Session),payload=Encoding.UTF8.GetBytes("opaque-inner-peer-tls-test");var frame=new byte[prefix.Length+payload.Length];Buffer.BlockCopy(prefix,0,frame,0,prefix.Length);Buffer.BlockCopy(payload,0,frame,prefix.Length,payload.Length);var read=Task.Run(()=>DiscoveryClient.ReadFrame(second.Tls,frame.Length));if(proveIdle)System.Threading.Thread.Sleep(11000);DiscoveryClient.WriteFrame(first.Tls,frame);Require(read.Wait(3000),description+" did not survive an idle interval");var received=read.Result;Require(Convert.ToBase64String(received)==Convert.ToBase64String(frame),description+" changed opaque bytes");}}
    public static int Main(string[] args){
        try {
            string host=args[0],pin=args[1];int port=Int32.Parse(args[2]);string adminPipe=args.Length>3&&args[3]!="--after-restart"&&args[3]!="--turn-disabled"?args[3]:"";
            if(args.Length>3&&args[3]=="--after-restart") { var aliceAfterRestart=new DiscoveryClient(host,port,pin);aliceAfterRestart.Login("alice-7f3k","correct horse battery staple");var bobAfterRestart=aliceAfterRestart.Search("bob-4m2q");Require(bobAfterRestart.PublicIdentity=="peer-public-fingerprint-bob-replacement-0123456789","server restart lost replacement account/device identity");Require(!aliceAfterRestart.GetFriendState().Friends.Exists(x=>x.AccountId==bobAfterRestart.AccountId),"deleted account relationship survived server restart");Console.WriteLine("PASS: durable retained account and replacement account state survived server restart.");return 0; }
            if(args.Length>3&&args[3]=="--turn-disabled"){var disabled=new DiscoveryClient(host,port,pin);disabled.Register("turn-disabled-7f3k","turn disabled password","peer-public-fingerprint-turn-disabled-0123456789");Require(Fails(()=>disabled.GetMediaTurnCredentials("peer-public-fingerprint-turn-disabled-0123456789")),"disabled TURN issuer returned credentials");Console.WriteLine("PASS: disabled TURN issuer rejects credential requests without affecting authenticated discovery.");return 0;}
            string turnSecret=Environment.GetEnvironmentVariable("PEERCHAT_TEST_TURN_SECRET")??"";Require(turnSecret.Length>=16,"missing TURN integration-test secret");
            var alice=new DiscoveryClient(host,port,pin);alice.Register("alice-7f3k","correct horse battery staple","peer-public-fingerprint-alice-0123456789");Require(alice.SupportsRelayOnlyPresence,"server did not advertise relay-only presence capability");alice.ReportPresence("peer-public-fingerprint-alice-0123456789");
            Require(Fails(()=>new DiscoveryClient(host,port,pin).GetMediaTurnCredentials("peer-public-fingerprint-alice-0123456789")),"anonymous TURN credential request succeeded");
            Require(Fails(()=>alice.GetMediaTurnCredentials("peer-public-fingerprint-not-owned-0123456789")),"TURN credential request accepted an unowned device identity");
            long credentialBefore=DateTimeOffset.UtcNow.ToUnixTimeSeconds();var turnOne=alice.GetMediaTurnCredentials("peer-public-fingerprint-alice-0123456789");long credentialAfter=DateTimeOffset.UtcNow.ToUnixTimeSeconds();Require(turnOne.Host=="turn.test.invalid"&&turnOne.Port==3478&&turnOne.Transport=="udp","TURN credential response returned the wrong route metadata");Require(turnOne.ExpiresUtc>=credentialBefore+590&&turnOne.ExpiresUtc<=credentialAfter+610,"TURN credential expiry did not honor the configured short TTL");var usernameParts=turnOne.Username.Split(':');Require(usernameParts.Length==4&&usernameParts[0]==turnOne.ExpiresUtc.ToString()&&usernameParts[1]==alice.AccountId.ToString()&&usernameParts[2].Length==16&&usernameParts[3].Length>=32,"TURN credential username was not a coturn REST expiry/account/device/nonce value");Require(turnOne.Password==CoturnPassword(turnOne.Username,turnSecret),"TURN credential password was not a standard coturn REST HMAC-SHA1 credential");Require(turnOne.Password!=turnSecret&&turnOne.Username!=turnSecret,"TURN shared secret leaked in a normal credential response");var turnTwo=alice.GetMediaTurnCredentials("peer-public-fingerprint-alice-0123456789");Require(turnTwo.Username!=turnOne.Username&&turnTwo.Password!=turnOne.Password,"TURN credential issuer reused a temporary credential");for(int issue=0;issue<4;issue++)alice.GetMediaTurnCredentials("peer-public-fingerprint-alice-0123456789");Require(Fails(()=>alice.GetMediaTurnCredentials("peer-public-fingerprint-alice-0123456789")),"TURN credential issuer did not rate-limit repeated issuance");
            Require(Fails(()=>{var duplicate=new DiscoveryClient(host,port,pin);duplicate.Register("alice-7f3k","other-password","peer-public-fingerprint-duplicate-0123456789");}),"duplicate username accepted");
            Require(Fails(()=>{var invalid=new DiscoveryClient(host,port,pin);invalid.Login("alice-7f3k","wrong password");}),"invalid login accepted");
            var logoutClient=new DiscoveryClient(host,port,pin);logoutClient.Login("alice-7f3k","correct horse battery staple");string revoked=logoutClient.SessionToken;logoutClient.Logout();Require(Fails(()=>new DiscoveryClient(host,port,pin){SessionToken=revoked}.RefreshSessionInfo()),"logout did not invalidate only that server session");Require(Fails(()=>new DiscoveryClient(host,port,pin){SessionToken=revoked}.GetMediaTurnCredentials("peer-public-fingerprint-alice-0123456789")),"logout-invalidated session could issue TURN credentials");Require(alice.GetFriendState()!=null,"logout invalidated a different session for the same account");
            var bob=new DiscoveryClient(host,port,pin);bob.Register("bob-4m2q","another correct password","peer-public-fingerprint-bob-0123456789");bob.ReportPresence("peer-public-fingerprint-bob-0123456789");
            Require(Fails(()=>bob.ReportPresence("peer-public-fingerprint-alice-0123456789")),"one account silently claimed another account's device identity");
            // The account exists but deliberately has no active discovery session or presence.
            // Pending requests must survive until this offline recipient signs in later.
            var offlineCreator=new DiscoveryClient(host,port,pin);offlineCreator.Register("offline-2m2","offline account password","peer-public-fingerprint-offline-0123456789");
            var offlineIdentity=bob.Search("offline-2m2");Require(!offlineIdentity.Online,"offline account unexpectedly appeared online");Require(bob.SendFriendRequest(offlineIdentity.AccountId)=="pending","offline recipient request was not pending");Require(bob.CancelFriendRequest(offlineIdentity.AccountId)=="cancelled","outgoing request cancellation failed");
            var offlineRecipient=new DiscoveryClient(host,port,pin);offlineRecipient.Login("offline-2m2","offline account password");var bobForOffline=offlineRecipient.Search("bob-4m2q");Require(offlineRecipient.GetFriendState().Incoming.Count==0,"cancelled request remained for offline recipient");Require(bob.SendFriendRequest(offlineIdentity.AccountId)=="pending","offline recipient request could not be resent");Require(offlineRecipient.GetFriendState().Incoming.Exists(x=>x.AccountId==bobForOffline.AccountId),"offline recipient did not recover pending request after login");Require(offlineRecipient.RespondToFriendRequest(bobForOffline.AccountId,false)=="rejected","offline recipient could not reject recovered request");
            var found=bob.Search("alice-7f3k");Require(found.Username=="alice-7f3k","wrong username returned");Require(found.PublicIdentity=="peer-public-fingerprint-alice-0123456789","wrong public identity returned");Require(found.Online,"presence was not returned");
            var suggestions=bob.Suggest("ALICE");Require(suggestions.Count==1&&suggestions[0].Username=="alice-7f3k","case-insensitive prefix suggestions failed");
            Require(Fails(()=>bob.Search("bob-4m2q")),"exact discovery returned the signed-in account");Require(bob.Suggest("bob").Count==0,"suggestions returned the signed-in account");
            var bobIdentity=alice.Search("bob-4m2q");Require(bob.SendFriendRequest(found.AccountId)=="pending","friend request was not pending");Require(Fails(()=>bob.SendFriendRequest(found.AccountId)),"duplicate friend request accepted");Require(alice.GetFriendState().Incoming.Exists(x=>x.AccountId==bobIdentity.AccountId),"offline-safe incoming request was not returned");RelayRoundTrip(alice,"peer-public-fingerprint-alice-0123456789",bobIdentity.AccountId,"peer-public-fingerprint-bob-0123456789",bob,found.AccountId,"pending friend-add relay");Require(Fails(()=>Attach(offlineRecipient,"peer-public-fingerprint-offline-0123456789",found.AccountId,"peer-public-fingerprint-alice-0123456789")),"unrelated account attached to relay");Require(alice.RespondToFriendRequest(bobIdentity.AccountId,true)=="friends","friend request acceptance failed");Require(alice.GetFriendState().Friends.Exists(x=>x.AccountId==bobIdentity.AccountId&&x.Online),"accepted friendship or online presence missing for recipient");Require(bob.GetFriendState().Friends.Exists(x=>x.AccountId==found.AccountId&&x.Online),"accepted friendship or online presence missing for sender");RelayRoundTrip(alice,"peer-public-fingerprint-alice-0123456789",bobIdentity.AccountId,"peer-public-fingerprint-bob-0123456789",bob,found.AccountId,"established-friend relay",true);
            Require(alice.RemoveFriend(bobIdentity.AccountId)=="removed","friend removal failed");Require(bob.SendFriendRequest(found.AccountId)=="pending","second friend request was not pending");Require(alice.SendFriendRequest(bobIdentity.AccountId)=="accepted_crossed","crossed request did not become friendship");Require(alice.SetBlocked(bobIdentity.AccountId,true)=="blocked","block failed");Require(Fails(()=>bob.SendFriendRequest(found.AccountId)),"blocked user could send a friend request");Require(Fails(()=>bob.Search("alice-7f3k")),"blocked account remained visible to exact discovery");Require(bob.Suggest("alice").Count==0,"blocked account remained visible to suggestions");Require(alice.SetBlocked(bobIdentity.AccountId,false)=="unblocked","unblock failed");Require(bob.SendFriendRequest(found.AccountId)=="pending","request after unblock failed");Require(alice.RespondToFriendRequest(bobIdentity.AccountId,false)=="rejected","reject failed");
            Require(bob.SendFriendRequest(found.AccountId)=="pending","rejected request could not be resent");Require(alice.RespondToFriendRequest(bobIdentity.AccountId,true)=="friends","final friendship acceptance failed");
            // New privacy-aware clients can remain present and relay-reachable without placing a
            // direct endpoint in ordinary friend state. Legacy requests omit the flag and retain
            // their prior behavior, so the protocol remains additive/version-compatible.
            var relayOnly=alice.ReportPresence("peer-public-fingerprint-alice-0123456789","",0,"",0,false);Require(!relayOnly.DirectCandidatesEnabled&&relayOnly.EndpointPort==0&&String.IsNullOrEmpty(relayOnly.EndpointHost),"relay-only presence returned a direct endpoint");var relayOnlyFriend=bob.GetFriendState().Friends.Find(x=>x.AccountId==found.AccountId);Require(relayOnlyFriend!=null&&relayOnlyFriend.Online&&relayOnlyFriend.EndpointPort==0&&String.IsNullOrEmpty(relayOnlyFriend.EndpointHost)&&relayOnlyFriend.PublicEndpointPort==0&&String.IsNullOrEmpty(relayOnlyFriend.PublicEndpointHost),"relay-only presence leaked a direct endpoint through friend state");
            var request=alice.RequestP2p(bobIdentity.AccountId,"peer-public-fingerprint-alice-0123456789","peer-public-fingerprint-bob-0123456789");string requestId=(string)request["requestId"];Require(requestId.Length==43,"P2P request ID was not an unpredictable session token");Require(Fails(()=>bob.SubmitP2pCandidate(requestId,"peer-public-fingerprint-bob-0123456789","10.0.0.2",7777)),"candidate was released before mutual consent");bob.ConsentP2p(requestId,"peer-public-fingerprint-bob-0123456789",true);var waiting=alice.SubmitP2pCandidate(requestId,"peer-public-fingerprint-alice-0123456789","10.0.0.1",7777);Require((string)waiting["state"]=="waiting_for_peer","first candidate unexpectedly disclosed peer route");var ready=bob.SubmitP2pCandidate(requestId,"peer-public-fingerprint-bob-0123456789","10.0.0.2",7777);Require((string)ready["peerHost"]=="10.0.0.1"&&Convert.ToInt32(ready["peerPort"])==7777,"mutually-consented candidate exchange returned wrong peer route");Require(Fails(()=>offlineRecipient.SubmitP2pCandidate(requestId,"peer-public-fingerprint-offline-0123456789","10.0.0.3",7777)),"third party reused P2P request");alice.CancelP2p(requestId,"peer-public-fingerprint-alice-0123456789");Require(Fails(()=>bob.SubmitP2pCandidate(requestId,"peer-public-fingerprint-bob-0123456789","10.0.0.2",7777)),"cancelled P2P request replayed");
            Require(Fails(()=>{var reusedDevice=new DiscoveryClient(host,port,pin);reusedDevice.Register("reuse-9q","password","peer-public-fingerprint-bob-0123456789");}),"duplicate public device identity accepted");
            Require(Fails(()=>bob.Search("bad space")),"malformed search accepted");Console.WriteLine("PASS: account/authentication, session-scoped logout, account/device ownership, presence/search, friend request, accept/reject, crossed requests, remove, block/unblock, and authoritative friend state.");
            if(String.IsNullOrEmpty(adminPipe))throw new Exception("missing local admin pipe for account deletion regression");for(int index=0;index<28;index++){string suffix=index.ToString("D2");var sample=new DiscoveryClient(host,port,pin);sample.Register("test-alpha-"+suffix,"test account password","peer-public-fingerprint-admin-sample-"+suffix+"-0123456789");}
            var blank=AdminAccounts(adminPipe,"");Require((bool)blank["ok"]&&((ArrayList)blank["accounts"]).Count==25&&Convert.ToBoolean(blank["hasMore"]),"blank admin search did not return a bounded default account page");var secondPage=AdminAccounts(adminPipe,"",25);Require((bool)secondPage["ok"]&&((ArrayList)secondPage["accounts"]).Count>0,"admin account Load More page was empty");var partial=AdminAccounts(adminPipe,"ALPHA");Require((bool)partial["ok"]&&((ArrayList)partial["accounts"]).Count==25,"case-insensitive partial admin search failed");var exactPage=AdminAccounts(adminPipe,"test-alpha-07");var exactRows=(ArrayList)exactPage["accounts"];Require((bool)exactPage["ok"]&&exactRows.Count==1&&String.Equals((string)((Dictionary<string,object>)exactRows[0])["username"],"test-alpha-07",StringComparison.OrdinalIgnoreCase),"exact admin search did not deterministically resolve one account");var exactRow=(Dictionary<string,object>)exactRows[0];Require(exactRow.ContainsKey("accountId")&&exactRow.ContainsKey("createdUtc")&&exactRow.ContainsKey("lastActiveUtc")&&exactRow.ContainsKey("online")&&exactRow.ContainsKey("deviceCount")&&!exactRow.ContainsKey("password_hash")&&!exactRow.ContainsKey("sessionToken"),"admin account result exposed the wrong metadata");Require(!(bool)Admin(adminPipe,"DELETE_ACCOUNT 999999999")["ok"],"stale admin account ID was deleted");
            var lookup=Admin(adminPipe,"ACCOUNT_LOOKUP "+Convert.ToBase64String(Encoding.UTF8.GetBytes("bob-4m2q")));Require((bool)lookup["ok"]&&Convert.ToInt64(lookup["accountId"])==bobIdentity.AccountId,"admin lookup did not resolve the exact account");var deleted=Admin(adminPipe,"DELETE_ACCOUNT "+bobIdentity.AccountId);Require((bool)deleted["ok"]&&Convert.ToBoolean(deleted["disconnectedActiveSession"]),"active selected account deletion did not report session disconnect");Require(Fails(()=>bob.RefreshSessionInfo()),"deleted account session remained valid");Require(Fails(()=>alice.Search("bob-4m2q")),"deleted account remained discoverable");Require(!alice.GetFriendState().Friends.Exists(x=>x.AccountId==bobIdentity.AccountId),"deleted account friendship remained visible");var afterDelete=AdminAccounts(adminPipe,"bob-4m2q");Require((bool)afterDelete["ok"]&&((ArrayList)afterDelete["accounts"]).Count==0,"deleted selected account remained in admin results");var replacement=new DiscoveryClient(host,port,pin);replacement.Register("bob-4m2q","replacement password","peer-public-fingerprint-bob-replacement-0123456789");Console.WriteLine("PASS: paged local admin account browse/search safely selected stable IDs and account deletion revoked active sessions, removed results/relationships, and released the username without touching client storage.");return 0;
        }catch(Exception error){Console.Error.WriteLine("FAIL: "+error.Message);return 1;}
    }
}
}
